package org.pocketlore.app;
import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import org.json.*;
/** Isolated real production archive/library tests; never seeds or clears the user's catalog. */
public final class DocumentFormatsInstrumentation extends Instrumentation {
 Bundle args;JSONObject report=new JSONObject();JSONArray assertions=new JSONArray();
 void ok(boolean condition,String label)throws Exception{if(!condition)throw new AssertionError(label);assertions.put(label);}
 public void onCreate(Bundle b){args=b;super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{
  String run=args.getString("run_id","");if(!run.matches("[A-Za-z0-9-]{8,80}"))throw new IOException("Missing isolated run identity");File root=new File(getTargetContext().getFilesDir(),"document-formats-"+run);if(!root.mkdir())throw new IOException("Refuse reuse of existing test store");File fixtures=new File(getContext().getFilesDir(),"format-fixtures");JSONObject oracle=new JSONObject(new String(Files.readAllBytes(new File(fixtures,"oracle.json").toPath()),StandardCharsets.UTF_8));JSONArray identities=new JSONArray();PackLibrary library=new PackLibrary(root);List<String> hashes=new ArrayList<>();
  for(String ext:new String[]{"docx","pptx","odt","odp","epub","html"}){
   String name="fixture."+ext;byte[] raw=Files.readAllBytes(new File(fixtures,name).toPath());byte[] archive=PersonalDocuments.convert(new ByteArrayInputStream(raw),name,"Authored CC0 fixture","2026-01-01","fixture://"+name,getTargetContext().getCacheDir(),()->false);KnowledgePack parsed=KnowledgePack.read(new ByteArrayInputStream(archive),true);JSONObject expected=oracle.getJSONObject(name);JSONArray paragraphs=expected.optJSONArray("paragraphs");if(paragraphs==null){paragraphs=new JSONArray();JSONArray parts=expected.optJSONArray("spine_order");if(parts==null)parts=expected.getJSONArray("slides_in_presentation_relationship_order");for(int i=0;i<parts.length();i++){JSONArray a=parts.getJSONObject(i).getJSONArray("paragraphs");for(int j=0;j<a.length();j++)paragraphs.put(a.getString(j));}}
   ok(parsed.rows.size()==paragraphs.length(),ext+"_passage_count");for(int i=0;i<paragraphs.length();i++)ok(parsed.rows.get(i)[5].equals(paragraphs.getString(i)),ext+"_exact_passage_"+i);library.install(new ByteArrayInputStream(archive),()->false,archive.length);hashes.add(parsed.sha256);
   ByteArrayOutputStream exported=new ByteArrayOutputStream();library.exportCollection(parsed.sha256,exported,()->false);ok(Arrays.equals(archive,exported.toByteArray()),ext+"_portable_exact_original_archive");File second=new File(root,"roundtrip-"+ext);KnowledgePack round=KnowledgePack.read(new ByteArrayInputStream(exported.toByteArray()),true);new PackLibrary(second).install(new ByteArrayInputStream(exported.toByteArray()),()->false,archive.length);ok(round.documentKeys.equals(parsed.documentKeys),ext+"_source_identity_roundtrip");
   ByteArrayOutputStream forged=new ByteArrayOutputStream();try(ZipInputStream zin=new ZipInputStream(new ByteArrayInputStream(archive));ZipOutputStream zout=new ZipOutputStream(forged)){ZipEntry e;while((e=zin.getNextEntry())!=null){byte[] b=PersonalDocuments.read(zin,PersonalDocuments.MAX_INPUT,()->false);if(e.getName().equals("personal.json")){JSONObject m=new JSONObject(new String(b,StandardCharsets.UTF_8));m.put("extractor_identity","Forged extractor");b=m.toString().getBytes(StandardCharsets.UTF_8);}PersonalDocuments.put(zout,e.getName(),b);}}
   boolean denied=false;try{KnowledgePack.read(new ByteArrayInputStream(forged.toByteArray()));}catch(Exception e){denied=true;}ok(denied,ext+"_forged_extractor_refused");identities.put(new JSONObject().put("format",ext).put("raw_sha256",KnowledgePack.hash(raw)).put("archive_sha256",parsed.sha256).put("passages",parsed.rows.size()));
  }
  ok(library.load().entries.size()==6,"six_collections");library.select(Collections.emptySet());ok(new PackLibrary(root).load().engine.research("conditional").hits.isEmpty(),"disabled_collections_excluded_after_reopen");library.select(new HashSet<>(hashes));ok(!new PackLibrary(root).load().engine.research("conditional").hits.isEmpty(),"enabled_retrieval_after_reopen");
  report.put("identities",identities).put("assertions",assertions).put("status","PASS_ISOLATED_INSTRUMENTATION").put("real_system_picker_completed",false).put("fresh_process_reopen",false);result.putString("report",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{report.put("status","FAIL").put("error",e.toString()).put("assertions",assertions);}catch(Exception ignored){}result.putString("report",report.toString());finish(Activity.RESULT_CANCELED,result);}}
}
